//! How English words sound: syllable counts and rhyme keys. A port of
//! `src/lib/verse/pronounce.ts`.
//!
//! The table is the one the browser uses, and literally the same file:
//! `src/lib/verse/pron-en.ts`, generated by `scripts/build-pronunciation.mjs` from the CMU
//! Pronouncing Dictionary, is compiled into this binary as text and read here. There is no
//! second copy to fall out of step. (Its header carries the dictionary's licence notice.)
//!
//! In the browser the table is fetched on demand and may be missing; on the server it is
//! always present, so a lookup here answers "not known" only for a word the table lacks.

use std::collections::HashMap;
use std::sync::LazyLock;

use unicode_normalization::UnicodeNormalization;

/// The generated TypeScript module, as text.
const SOURCE: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../src/lib/verse/pron-en.ts"));

/// The characters that are vowels in a rhyme key (`KEY_VOWELS`).
const KEY_VOWELS: &str = "AauOWYeREiIoyUw";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Pronunciation {
    /// Syllable counts, the commonest pronunciation first. "fire" is [2, 1].
    pub counts: Vec<u32>,
    /// Rhyme keys: the sounds from the last stressed vowel on, one per pronunciation.
    pub keys: Vec<&'static str>,
}

/// The table's data: what the module exports, between the back-ticks of its template
/// string. The generator refuses to write a table holding a back-tick, a backslash or
/// `${`, so the text between them is the string itself.
fn data() -> &'static str {
    const OPEN: &str = "export default `";
    let start = SOURCE.find(OPEN).expect("pron-en.ts exports a template string") + OPEN.len();
    let end = SOURCE.rfind('`').expect("pron-en.ts closes its template string");
    assert!(end > start, "pron-en.ts holds a table");
    &SOURCE[start..end]
}

/// `installPronunciation`: one line per rhyme key, `<key>\t<word><counts> <word><counts> …`.
static TABLE: LazyLock<HashMap<&'static str, Pronunciation>> = LazyLock::new(|| {
    let mut table: HashMap<&'static str, Pronunciation> = HashMap::new();
    for line in data().split('\n') {
        let Some(tab) = line.find('\t') else { continue };
        if tab < 1 {
            continue;
        }
        let key = &line[..tab];
        for entry in line[tab + 1..].split(' ') {
            // /^(.*?)(\d+)$/: the word, then every digit the entry ends in.
            let word = entry.trim_end_matches(|c: char| c.is_ascii_digit());
            let digits = &entry[word.len()..];
            if digits.is_empty() {
                continue;
            }
            match table.get_mut(word) {
                Some(p) => p.keys.push(key),
                None => {
                    let counts = digits.bytes().map(|b| u32::from(b - b'0')).collect();
                    table.insert(word, Pronunciation { counts, keys: vec![key] });
                }
            }
        }
    }
    table
});

/// Words in the table.
pub fn table_len() -> usize {
    TABLE.len()
}

/// A word as the table spells it: lower case, no accents, straight apostrophes, letters only.
fn plain(word: &str) -> String {
    word.nfd()
        .filter(|c| !('\u{300}'..='\u{36f}').contains(c))
        .collect::<String>()
        .to_lowercase()
        .chars()
        .map(|c| if matches!(c, '\u{2019}' | '\u{2018}' | '\u{2bc}') { '\'' } else { c })
        .filter(|c| c.is_ascii_lowercase() || *c == '\'')
        .collect()
}

/// What the table knows of an English word, or `None` when it is not in it.
pub fn pronounce(word: &str) -> Option<&'static Pronunciation> {
    let w = plain(word);
    TABLE.get(w.as_str()).or_else(|| TABLE.get(w.replace('\'', "").as_str()))
}

/// The last syllable of a rhyme key: from its last vowel on.
fn last_syllable(key: &str) -> &str {
    match key.rfind(|c: char| KEY_VOWELS.contains(c)) {
        Some(i) => &key[i..],
        None => key,
    }
}

/// Do two rhyme keys rhyme? Either they are the same, or their last syllables are and one
/// of the two words is stressed there.
fn keys_rhyme(a: &str, b: &str) -> bool {
    if a == b {
        return true;
    }
    let ta = last_syllable(a);
    ta == last_syllable(b) && (ta == a || ta == b)
}

/// Do two English words rhyme by sound, in any of their pronunciations? `None` when either
/// is not in the table: the caller falls back to spelling.
pub fn sound_rhyme(a: &str, b: &str) -> Option<bool> {
    let pa = pronounce(a)?;
    let pb = pronounce(b)?;
    Some(pa.keys.iter().any(|x| pb.keys.iter().any(|y| keys_rhyme(x, y))))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_the_generated_one_and_parses_whole() {
        // The dictionary alone is over a hundred thousand words.
        assert!(table_len() > 120_000, "{} words", table_len());
        assert!(!data().contains('`') && !data().contains('\\'));
        for word in ["hamlet", "macbeth", "ophelia", "thee", "thou", "tis", "o'er"] {
            assert!(pronounce(word).is_some(), "{word}");
        }
        assert!(pronounce("zzyzxqq").is_none());
    }

    #[test]
    fn counts_and_keys_come_out_as_written() {
        assert_eq!(pronounce("fire").map(|p| p.counts.clone()), Some(vec![2, 1]));
        assert_eq!(pronounce("stage").map(|p| p.counts.clone()), Some(vec![1]));
        assert_eq!(pronounce("Café").map(|p| p.counts[0]), Some(2));
        // An apostrophe typed either way finds the same word; one the table spells without is found too.
        assert_eq!(pronounce("don’t"), pronounce("don't"));
        assert!(pronounce("don't").is_some());
    }

    #[test]
    fn rhyme_is_heard_not_spelled() {
        for (a, b) in [("go", "so"), ("know", "show"), ("sky", "high"), ("day", "they"), ("time", "rhyme"), ("you", "true"),
            ("destiny", "free"), ("running", "king")] {
            assert_eq!(sound_rhyme(a, b), Some(true), "{a} / {b}");
        }
        for (a, b) in [("candle", "apple"), ("running", "morning"), ("stage", "large"), ("love", "move")] {
            assert_eq!(sound_rhyme(a, b), Some(false), "{a} / {b}");
        }
        assert_eq!(sound_rhyme("go", "zzyzxqq"), None);
    }
}
